import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';

class Login extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      txtUsername: '',
      txtPassword: ''
    };
  }

  btnLoginClick = (e) => {
    e.preventDefault();
    const { txtUsername, txtPassword } = this.state;

    if (txtUsername && txtPassword) {
      axios.post('/api/admin/login', { username: txtUsername, password: txtPassword }).then((res) => {
        if (res.data.token) {
          const { token, role } = res.data;
          
          // Lưu token vào Context và LocalStorage (BỎ setRole để tránh crash ứng dụng)
          this.context.setToken(token);
          this.context.setUsername(txtUsername);
          
          localStorage.setItem('token', token);
          localStorage.setItem('role', role);

          // PHÂN QUYỀN ĐIỀU HƯỚNG THEO ROLE
          if (role === 'admin') {
            window.location.href = '/admin/report';
          } else if (role === 'receptionist') {
            window.location.href = '/admin/reception';
          } else if (role === 'kitchen') {
            window.location.href = '/admin/kitchen';
          } else if (role === 'customer') {
            window.location.href = `http://localhost:3002?token=${token}`;
          }
        } else {
          alert(res.data.message);
        }
      }).catch(err => {
        console.error("Lỗi kết nối API đăng nhập:", err);
        alert("Lỗi kết nối đến máy chủ!");
      });
    } else {
      alert('Vui lòng nhập đầy đủ thông tin!');
    }
  };

  render() {
    if (this.context.token === '') {
      return (
        <div style={{ width: '300px', margin: '50px auto', textAlign: 'center' }}>
          <h2>ADMIN LOGIN</h2>
          <form>
            <div style={{ marginBottom: '10px' }}>
              <input
                type="text"
                placeholder="Username"
                value={this.state.txtUsername}
                onChange={(e) => this.setState({ txtUsername: e.target.value })}
              />
            </div>
            <div style={{ marginBottom: '10px' }}>
              <input
                type="password"
                placeholder="Password"
                value={this.state.txtPassword}
                onChange={(e) => this.setState({ txtPassword: e.target.value })}
              />
            </div>
            <input type="submit" value="LOGIN" onClick={(e) => this.btnLoginClick(e)} />
          </form>
        </div>
      );
    }
    return <div />;
  }
}

export default Login;
